type trailUpdateInputs struct { Status; StatusChanged; Title; TitleChanged; Body; BodyChanged; BodyFile; BodyFileChanged; Branch; LabelAdd; LabelRemove }

type trailUpdateEdits struct { status, title, body string }

func interactiveUpdateInputs(seed, edited trailUpdateEdits) trailUpdateInputs {
	return trailUpdateInputs{ Status: edited.status, StatusChanged: edited.status != seed.status, Title: edited.title, TitleChanged: edited.title != seed.title, Body: edited.body, BodyChanged: edited.body != seed.body }
}

func trailUpdateHasChanges(inputs) bool { return StatusChanged || TitleChanged || BodyChanged || len(LabelAdd)>0 || len(LabelRemove)>0 }

// runTrailUpdate: resolves trail (branch lookup vs selector), resolves body via resolveTrailBodyInput, interactive mode when noFlags.
// Interactive: rejects found.Number<=0 up front; seeds body from fetchTrailBody; if body load fails, warns + omits body field (bodyLoaded=false) so status/title stay editable; builds form fields dynamically; after form, interactiveUpdateInputs marks only edited fields.

func resolveTrailBodyInput(body, bodyFile string, bodyChanged, bodyFileChanged bool, stdin io.Reader) (string, bool, error) {
	if bodyChanged && bodyFileChanged { return "", false, errors.New("cannot combine --body with --body-file") }
	switch {
	case bodyFileChanged:
		if bodyFile == "-" { return readTrailBodyStdin(stdin) }
		data, err := os.ReadFile(bodyFile); if err != nil { return "", false, fmt.Errorf("read body file: %w", err) }
		return string(data), true, nil
	case bodyChanged:
		if body == "-" { return readTrailBodyStdin(stdin) }
		return body, true, nil
	default: return "", false, nil
	}
}
func readTrailBodyStdin(stdin io.Reader) (string, bool, error) { if stdin == nil { return "", false, errors.New("no stdin available...") }; data, err := io.ReadAll(stdin); ...; return string(data), true, nil }

func applyTrailUpdate(ctx, client, forge, owner, repo, found, inputs) error {
	if found.Number <= 0 { return fmt.Errorf("%s has no number yet; cannot update", describeTrailRef(found)) }
	path := trailNumberPath(...)
	metadataChanged := StatusChanged || TitleChanged || len(LabelAdd)>0 || len(LabelRemove)>0
	if metadataChanged { req := buildTrailUpdateRequest(found, {Status,StatusChanged,Title,TitleChanged,LabelAdd,LabelRemove}); if err := patchTrail(ctx, client, path, req); err != nil { return err } }
	if inputs.BodyChanged { if err := patchTrail(ctx, client, path, api.TrailUpdateRequest{Body: &inputs.Body}); err != nil { if metadataChanged { return fmt.Errorf("metadata updated, but body update failed: %w", err) }; return err } }
	return nil
}
func patchTrail(ctx, client, path, req) error { resp, err := client.Patch(...); ...; checkTrailResponse; DecodeJSON; return nil }

